            waitpid(pid, &status, 0);
            if (WEXITSTATUS(status) != 0) return WEXITSTATUS(status);
            free(out_obj);
        }
        return 0;
    }

    if (mode == MODE_RUN || mode == MODE_EXE) {
        char target_exec[256];
        if (mode == MODE_RUN) {
            snprintf(target_exec, sizeof(target_exec), "/tmp/tcc_run_%d", getpid());
        } else {
            if (outfile) {
                snprintf(target_exec, sizeof(target_exec), "%s", outfile);
