            } else {
                snprintf(target_exec, sizeof(target_exec), "a.out");
            }
        }

        if (verbose_level >= 1) {
            for (int i = 0; i < input_files.count; i++) {
                printf("-> %s\n", input_files.data[i]);
            }
            printf("<- %s\n", target_exec);
        }

        StringVec gcc_cmd; vec_init(&gcc_cmd);
        vec_push(&gcc_cmd, "gcc");
        vec_push(&gcc_cmd, "-fno-diagnostics-show-caret");
        vec_push(&gcc_cmd, "-fno-show-column");

        if (is_shared) vec_push(&gcc_cmd, "-shared");
        if (is_static) vec_push(&gcc_cmd, "-static");
        if (rdynamic) vec_push(&gcc_cmd, "-rdynamic");
        if (relocatable) vec_push(&gcc_cmd, "-r");
        if (pthread) vec_push(&gcc_cmd, "-pthread");
        if (soname) {
            char buf[512]; snprintf(buf, sizeof(buf), "-Wl,-soname=%s", soname);
            vec_push(&gcc_cmd, buf);
        }

        for (int g = 0; g < gcc_flags.count; g++) {
            vec_push(&gcc_cmd, gcc_flags.data[g]);
        }
        for (int d = 0; d < defs.count; d++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-D%s", defs.data[d]);
            vec_push(&gcc_cmd, buf);
        }
        for (int u = 0; u < undefines.count; u++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-U%s", undefines.data[u]);
            vec_push(&gcc_cmd, buf);
        }
        for (int inc = 0; inc < include_dirs.count; inc++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-I%s", include_dirs.data[inc]);
            vec_push(&gcc_cmd, buf);
        }
        for (int sys = 0; sys < isystem_dirs.count; sys++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-isystem%s", isystem_dirs.data[sys]);
            vec_push(&gcc_cmd, buf);
        }
        for (int incf = 0; incf < include_files.count; incf++) {
            vec_push(&gcc_cmd, "-include");
            vec_push(&gcc_cmd, include_files.data[incf]);
        }
        for (int ld = 0; ld < lib_dirs.count; ld++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-L%s", lib_dirs.data[ld]);
            vec_push(&gcc_cmd, buf);
        }

        for (int i = 0; i < input_files.count; i++) {
            vec_push(&gcc_cmd, input_files.data[i]);
        }

        for (int l = 0; l < libs.count; l++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-l%s", libs.data[l]);
            vec_push(&gcc_cmd, buf);
        }
        for (int lo = 0; lo < linker_opts.count; lo++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-Wl,%s", linker_opts.data[lo]);
            vec_push(&gcc_cmd, buf);
        }

        vec_push(&gcc_cmd, "-o");
        vec_push(&gcc_cmd, target_exec);
        vec_push(&gcc_cmd, NULL);

        pid_t pid = fork();
        if (pid == 0) {
            execvp("gcc", gcc_cmd.data);
            exit(1);
        }
        int status = 0;
        waitpid(pid, &status, 0);
        if (WEXITSTATUS(status) != 0) return WEXITSTATUS(status);

        if (mode == MODE_RUN) {
            StringVec exec_cmd; vec_init(&exec_cmd);
            vec_push(&exec_cmd, input_files.data[0]);
            for (int r = 0; r < run_args.count; r++) {
                vec_push(&exec_cmd, run_args.data[r]);
            }
            vec_push(&exec_cmd, NULL);

            pid_t run_pid = fork();
            if (run_pid == 0) {
                if (rstdin_file) {
                    int fd = open(rstdin_file, O_RDONLY);
                    if (fd >= 0) {
                        dup2(fd, 0);
                        close(fd);
                    }
                }
                execv(target_exec, exec_cmd.data);
                exit(1);
            }
            int run_status = 0;
            waitpid(run_pid, &run_status, 0);
            unlink(target_exec);
            return WEXITSTATUS(run_status);
        }
    }

    return 0;
}
