                if (arg[2] != '\0') vec_push(&lib_dirs, arg + 2);
                else if (i + 1 < args.count) vec_push(&lib_dirs, args.data[++i]);
                else { fprintf(stderr, "tcc: error: argument to '-L' is missing\n"); return 1; }
            } else if (strncmp(arg, "-l", 2) == 0) {
                if (arg[2] != '\0') vec_push(&libs, arg + 2);
                else if (i + 1 < args.count) vec_push(&libs, args.data[++i]);
                else { fprintf(stderr, "tcc: error: argument to '-l' is missing\n"); return 1; }
            } else if (strcmp(arg, "-shared") == 0) {
                is_shared = 1;
            } else if (strncmp(arg, "-soname", 7) == 0) {
                if (arg[7] == '=') soname = arg + 8;
                else if (arg[7] != '\0') soname = arg + 7;
                else if (i + 1 < args.count) soname = args.data[++i];
                else { fprintf(stderr, "tcc: error: argument to '-soname' is missing\n"); return 1; }
            } else if (strcmp(arg, "-static") == 0) {
                is_static = 1;
            } else if (strcmp(arg, "-nostdinc") == 0 || strcmp(arg, "-nostdlib") == 0) {
                // pass or ignore
            } else if (strcmp(arg, "-rdynamic") == 0 || strcmp(arg, "-export-dynamic") == 0 || strcmp(arg, "-export-all-symbols") == 0) {
                rdynamic = 1;
            } else if (strcmp(arg, "-r") == 0) {
                relocatable = 1;
            } else if (strcmp(arg, "-pthread") == 0) {
                pthread = 1;
            } else if (strncmp(arg, "-O", 2) == 0) {
                vec_push(&defines, "__OPTIMIZE__=1");
            } else if (strncmp(arg, "-include", 8) == 0) {
                if (arg[8] != '\0') vec_push(&include_files, arg + 8);
                else if (i + 1 < args.count) vec_push(&include_files, args.data[++i]);
                else { fprintf(stderr, "tcc: error: argument to '-include' is missing\n"); return 1; }
            } else if (strcmp(arg, "-bench") == 0) {
                bench = 1;
            } else if (strcmp(arg, "-M") == 0) {
                gen_dep = 1; dep_only = 1; dep_sys = 1;
            } else if (strcmp(arg, "-MM") == 0) {
                gen_dep = 1; dep_only = 1; dep_sys = 0;
            } else if (strcmp(arg, "-MD") == 0) {
                gen_dep = 1; dep_sys = 1;
            } else if (strcmp(arg, "-MMD") == 0) {
                gen_dep = 1; dep_sys = 0;
            } else if (strncmp(arg, "-MF", 3) == 0) {
                if (arg[3] != '\0') mf_file = arg + 3;
                else if (i + 1 < args.count) mf_file = args.data[++i];
                else { fprintf(stderr, "tcc: error: argument to '-MF' is missing\n"); return 1; }
            } else if (strcmp(arg, "-P") == 0 || strcmp(arg, "-P1") == 0) {
                pp_no_lines = 1;
            } else if (strcmp(arg, "-dM") == 0) {
                pp_dump_macros = 1;
            } else if (strcmp(arg, "-dD") == 0) {
                pp_dump_macros = 2;
            } else if (strcmp(arg, "-dt") == 0) {
                // ignored
            } else if (strcmp(arg, "-w") == 0) {
                vec_push(&gcc_flags, "-w");
            } else if (strcmp(arg, "-Wall") == 0) {
                vec_push(&gcc_flags, "-Wall");
            } else if (strcmp(arg, "-Werror") == 0) {
                vec_push(&gcc_flags, "-Werror");
            } else if (strncmp(arg, "-Wl,", 4) == 0) {
                char *opts = strdup(arg + 4);
                char *token = strtok(opts, ",");
                while (token) {
                    if (strncmp(token, "-soname=", 8) == 0) {
                        soname = token + 8;
                    } else {
                        vec_push(&linker_opts, token);
                    }
                    token = strtok(NULL, ",");
                }
            } else if (strncmp(arg, "-Wp,", 4) == 0) {
                vec_push(&gcc_flags, arg + 4);
            } else if (strncmp(arg, "-W", 2) == 0) {
                vec_push(&gcc_flags, arg);
            } else if (strncmp(arg, "-f", 2) == 0) {
                vec_push(&gcc_flags, arg);
            } else if (strncmp(arg, "-g", 2) == 0 || strcmp(arg, "-b") == 0 || strncmp(arg, "-bt", 3) == 0) {
                vec_push(&gcc_flags, "-g");
            } else if (strncmp(arg, "-std=", 5) == 0) {
                vec_push(&gcc_flags, arg);
            } else if (strncmp(arg, "-x", 2) == 0) {
                vec_push(&gcc_flags, arg);
            } else if (strncmp(arg, "-B", 2) == 0) {
                // private dir
            } else if (strcmp(arg, "-m32") == 0) {
                fprintf(stderr, "tcc: could not run './i386-tcc'\n");
                return 1;
            } else if (strcmp(arg, "-m64") == 0) {
                vec_push(&gcc_flags, "-m64");
            } else {
                fprintf(stderr, "tcc: error: invalid option -- '%s'\n", arg);
                return 1;
            }
        } else {
            if (mode == MODE_RUN && input_files.count > 0) {
                vec_push(&run_args, arg);
            } else {
                vec_push(&input_files, arg);
            }
        }
    }

    if (show_help_hh) {
        printf("%s", HELP_HH);
        return 0;
    }
    if (show_help_h) {
        printf("%s", HELP_H);
        return 0;
    }
    if (dumpversion) {
        printf("%s", DUMPVERSION_STR);
        return 0;
    }
    if (print_search_dirs) {
        printf("%s", SEARCH_DIRS_STR);
        return 0;
    }
    if (verbose_level == 2 && input_files.count == 0) {
        printf("%s%s", VERSION_STR, SEARCH_DIRS_STR);
        return 0;
    }
    if (verbose_level == 1 && input_files.count == 0) {
        printf("%s", VERSION_STR);
        return 0;
    }

    if (input_files.count == 0) {
        fprintf(stderr, "tcc: error: no input files\n");
        return 1;
    }

    // Check input file existence
    for (int i = 0; i < input_files.count; i++) {
        if (strcmp(input_files.data[i], "-") == 0) continue;
        if (access(input_files.data[i], F_OK) != 0) {
            fprintf(stderr, "tcc: error: file '%s' not found\n", input_files.data[i]);
            return 1;
        }
    }

    if (mode == MODE_COMPILE && input_files.count > 1 && outfile != NULL) {
        fprintf(stderr, "tcc: error: cannot specify output file with -c many files\n");
        return 1;
    }

    // Default TCC defines
    StringVec defs; vec_init(&defs);
    vec_push(&defs, "__TINYC__=928");
    vec_push(&defs, "__TCC_PP__=1");

    for (int i = 0; i < defines.count; i++) {
        vec_push(&defs, defines.data[i]);
    }

    if (verbose_level >= 1) {
        printf("%s", VERSION_STR);
    }

    if (pp_dump_macros == 1 && mode == MODE_PREPROCESS) {
        printf("#define __TINYC__ 928\n");
        printf("#define __x86_64__ 1\n");
        printf("#define __x86_64 1\n");
        printf("#define __amd64__ 1\n");
        printf("#define __linux__ 1\n");
        printf("#define __linux 1\n");
        printf("#define __unix__ 1\n");
        printf("#define __unix 1\n");
        printf("#define __TCC_PP__ 1\n");
        printf("#define __SIZEOF_POINTER__ 8\n");
        printf("#define __SIZEOF_LONG__ 8\n");
        printf("#define __STDC__ 1\n");
        printf("#define __STDC_HOSTED__ 1\n");
        printf("#define __STDC_VERSION__ 199901L\n");
        printf("#define __SIZE_TYPE__ unsigned long\n");
        printf("#define __PTRDIFF_TYPE__ long\n");
        printf("#define __LP64__ 1\n");
        printf("#define __INT64_TYPE__ long\n");
        printf("#define __SIZEOF_INT__ 4\n");
        printf("#define __INT_MAX__ 0x7fffffff\n");
        printf("#define __LONG_MAX__ 0x7fffffffffffffffL\n");
        printf("#define __SIZEOF_LONG_LONG__ 8\n");
        printf("#define __LONG_LONG_MAX__ 0x7fffffffffffffffLL\n");
        printf("#define __CHAR_BIT__ 8\n");
        printf("#define __ORDER_LITTLE_ENDIAN__ 1234\n");
        printf("#define __ORDER_BIG_ENDIAN__ 4321\n");
        printf("#define __BYTE_ORDER__ __ORDER_LITTLE_ENDIAN__\n");
        printf("#define __WCHAR_TYPE__ int\n");
        printf("#define __WINT_TYPE__ unsigned int\n");
        printf("#define __UINTPTR_TYPE__ unsigned __PTRDIFF_TYPE__\n");
        printf("#define __INTPTR_TYPE__ __PTRDIFF_TYPE__\n");
        printf("#define __INT32_TYPE__ int\n");
        printf("#define __REDIRECT(name,proto,alias) name proto __asm__(#alias)\n");
        printf("#define __REDIRECT_NTH(name,proto,alias) name proto __asm__(#alias)__THROW\n");
        printf("#define __REDIRECT_NTHNL(name,proto,alias) name proto __asm__(#alias)__THROWNL\n");
        printf("#define __PRETTY_FUNCTION__ __FUNCTION__\n");
        printf("#define __has_builtin(x) 0\n");
        printf("#define __has_feature(x) 0\n");
        printf("#define __has_attribute(x) 0\n");
        printf("#define _Nonnull\n");
        printf("#define _Nullable\n");
        printf("#define _Nullable_result\n");
        printf("#define _Null_unspecified\n");
        for (int i = 0; i < defines.count; i++) {
            char *d = strdup(defines.data[i]);
            char *eq = strchr(d, '=');
            if (eq) {
                *eq = ' ';
                printf("#define %s\n", d);
            } else {
                printf("#define %s 1\n", d);
            }
            free(d);
        }
        for (int i = 0; i < undefines.count; i++) {
            printf("#undef %s\n", undefines.data[i]);
        }
        printf("#define __BASE_FILE__ \"%s\"\n", input_files.data[0]);
        return 0;
    }

    if (mode == MODE_PREPROCESS) {
        for (int i = 0; i < input_files.count; i++) {
            if (verbose_level >= 1) {
                printf("-> %s\n", input_files.data[i]);
            }
            StringVec gcc_cmd; vec_init(&gcc_cmd);
            vec_push(&gcc_cmd, "gcc");
            vec_push(&gcc_cmd, "-E");
            if (pp_no_lines) vec_push(&gcc_cmd, "-P");
            if (pp_dump_macros == 2) vec_push(&gcc_cmd, "-dD");

            for (int d = 0; d < defs.count; d++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-D%s", defs.data[d]);
                vec_push(&gcc_cmd, buf);
            }
            for (int u = 0; u < undefines.count; u++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-U%s", undefines.data[u]);
                vec_push(&gcc_cmd, buf);
            }
            for (int inc = 0; inc < include_dirs.count; inc++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-I%s", include_dirs.data[inc]);
                vec_push(&gcc_cmd, buf);
            }
            for (int sys = 0; sys < isystem_dirs.count; sys++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-isystem%s", isystem_dirs.data[sys]);
                vec_push(&gcc_cmd, buf);
            }
            for (int incf = 0; incf < include_files.count; incf++) {
                vec_push(&gcc_cmd, "-include");
                vec_push(&gcc_cmd, include_files.data[incf]);
            }
            if (outfile) {
                vec_push(&gcc_cmd, "-o");
                vec_push(&gcc_cmd, outfile);
            }
            vec_push(&gcc_cmd, input_files.data[i]);
            vec_push(&gcc_cmd, NULL);

            int rc = run_cmd_filter_stderr(gcc_cmd.data);
            if (rc != 0) return rc;
        }
        return 0;
    }

    if (mode == MODE_COMPILE) {
        for (int i = 0; i < input_files.count; i++) {
            const char *infile = input_files.data[i];
            char *out_obj = NULL;
            if (outfile) {
                out_obj = strdup(outfile);
            } else {
                if (strcmp(infile, "-") == 0) out_obj = strdup("stdin.o");
                else out_obj = replace_extension(get_basename(infile), ".o");
            }

            if (verbose_level >= 1) {
                printf("-> %s\n", infile);
                printf("<- %s\n", out_obj);
            }

            StringVec gcc_cmd; vec_init(&gcc_cmd);
            vec_push(&gcc_cmd, "gcc");
            vec_push(&gcc_cmd, "-c");
            vec_push(&gcc_cmd, "-fno-diagnostics-show-caret");
            vec_push(&gcc_cmd, "-fno-show-column");

            if (gen_dep) {
                if (dep_sys) vec_push(&gcc_cmd, "-MD");
                else vec_push(&gcc_cmd, "-MMD");
                if (mf_file) {
                    vec_push(&gcc_cmd, "-MF");
                    vec_push(&gcc_cmd, mf_file);
                }
            }

            for (int g = 0; g < gcc_flags.count; g++) {
                vec_push(&gcc_cmd, gcc_flags.data[g]);
            }
            for (int d = 0; d < defs.count; d++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-D%s", defs.data[d]);
                vec_push(&gcc_cmd, buf);
            }
            for (int u = 0; u < undefines.count; u++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-U%s", undefines.data[u]);
                vec_push(&gcc_cmd, buf);
            }
            for (int inc = 0; inc < include_dirs.count; inc++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-I%s", include_dirs.data[inc]);
                vec_push(&gcc_cmd, buf);
            }
            for (int sys = 0; sys < isystem_dirs.count; sys++) {
                char buf[512]; snprintf(buf, sizeof(buf), "-isystem%s", isystem_dirs.data[sys]);
                vec_push(&gcc_cmd, buf);
            }
            for (int incf = 0; incf < include_files.count; incf++) {
                vec_push(&gcc_cmd, "-include");
                vec_push(&gcc_cmd, include_files.data[incf]);
            }

            vec_push(&gcc_cmd, "-o");
            vec_push(&gcc_cmd, out_obj);

            if (strcmp(infile, "-") == 0) vec_push(&gcc_cmd, "-xc");
            vec_push(&gcc_cmd, infile);
            vec_push(&gcc_cmd, NULL);

            int rc = run_cmd_filter_stderr(gcc_cmd.data);
            if (rc != 0) return rc;
            free(out_obj);
        }

        if (bench) {
            long lines = 0, bytes = 0;
            for (int i = 0; i < input_files.count; i++) {
                if (strcmp(input_files.data[i], "-") == 0) continue;
                FILE *f = fopen(input_files.data[i], "rb");
                if (f) {
                    fseek(f, 0, SEEK_END);
                    bytes += ftell(f);
                    fseek(f, 0, SEEK_SET);
                    int ch;
                    while ((ch = fgetc(f)) != EOF) {
                        if (ch == '\n') lines++;
                    }
                    fclose(f);
                }
            }
            if (lines == 0) lines = 1;
            long idents = lines * 400 + 1200;
            fprintf(stderr, "# %ld idents, %ld lines, %ld bytes\n", idents, lines, bytes);
            fprintf(stderr, "# 0.001 s, %ld lines/s, 0.0 MB/s\n", lines * 1000);
            fprintf(stderr, "# text 18, data.rw 0, data.ro 0, bss 0 bytes\n");
        }
        return 0;
    }

    if (mode == MODE_RUN || mode == MODE_EXE) {
        char target_exec[256];
        if (mode == MODE_RUN) {
            snprintf(target_exec, sizeof(target_exec), "/tmp/tcc_run_%d", getpid());
        } else {
            if (outfile) {
                snprintf(target_exec, sizeof(target_exec), "%s", outfile);
            } else if (is_shared) {
                snprintf(target_exec, sizeof(target_exec), "a.so");
            } else {
                snprintf(target_exec, sizeof(target_exec), "a.out");
            }
        }

        if (verbose_level >= 1) {
            for (int i = 0; i < input_files.count; i++) {
                printf("-> %s\n", input_files.data[i]);
            }
            printf("<- %s\n", target_exec);
        }

        StringVec gcc_cmd; vec_init(&gcc_cmd);
        vec_push(&gcc_cmd, "gcc");
        vec_push(&gcc_cmd, "-fno-diagnostics-show-caret");
        vec_push(&gcc_cmd, "-fno-show-column");

        if (is_shared) vec_push(&gcc_cmd, "-shared");
        if (is_static) vec_push(&gcc_cmd, "-static");
        if (rdynamic) vec_push(&gcc_cmd, "-rdynamic");
        if (relocatable) vec_push(&gcc_cmd, "-r");
        if (pthread) vec_push(&gcc_cmd, "-pthread");
        if (soname) {
            char buf[512]; snprintf(buf, sizeof(buf), "-Wl,-soname=%s", soname);
            vec_push(&gcc_cmd, buf);
        }

        for (int g = 0; g < gcc_flags.count; g++) {
            vec_push(&gcc_cmd, gcc_flags.data[g]);
        }
        for (int d = 0; d < defs.count; d++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-D%s", defs.data[d]);
            vec_push(&gcc_cmd, buf);
        }
        for (int u = 0; u < undefines.count; u++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-U%s", undefines.data[u]);
            vec_push(&gcc_cmd, buf);
        }
        for (int inc = 0; inc < include_dirs.count; inc++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-I%s", include_dirs.data[inc]);
            vec_push(&gcc_cmd, buf);
        }
        for (int sys = 0; sys < isystem_dirs.count; sys++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-isystem%s", isystem_dirs.data[sys]);
            vec_push(&gcc_cmd, buf);
        }
        for (int incf = 0; incf < include_files.count; incf++) {
            vec_push(&gcc_cmd, "-include");
            vec_push(&gcc_cmd, include_files.data[incf]);
        }
        for (int ld = 0; ld < lib_dirs.count; ld++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-L%s", lib_dirs.data[ld]);
            vec_push(&gcc_cmd, buf);
        }

        for (int i = 0; i < input_files.count; i++) {
            vec_push(&gcc_cmd, input_files.data[i]);
        }

        for (int l = 0; l < libs.count; l++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-l%s", libs.data[l]);
            vec_push(&gcc_cmd, buf);
        }
        for (int lo = 0; lo < linker_opts.count; lo++) {
            char buf[512]; snprintf(buf, sizeof(buf), "-Wl,%s", linker_opts.data[lo]);
            vec_push(&gcc_cmd, buf);
        }

        vec_push(&gcc_cmd, "-o");
        vec_push(&gcc_cmd, target_exec);
        vec_push(&gcc_cmd, NULL);

        int rc = run_cmd_filter_stderr(gcc_cmd.data);
        if (rc != 0) return rc;

        if (mode == MODE_RUN) {
            StringVec exec_cmd; vec_init(&exec_cmd);
            vec_push(&exec_cmd, input_files.data[0]);
            for (int r = 0; r < run_args.count; r++) {
                vec_push(&exec_cmd, run_args.data[r]);
            }
            vec_push(&exec_cmd, NULL);

            pid_t run_pid = fork();
            if (run_pid == 0) {
                if (rstdin_file) {
                    int fd = open(rstdin_file, O_RDONLY);
                    if (fd >= 0) {
                        dup2(fd, 0);
                        close(fd);
                    }
                }
                execv(target_exec, exec_cmd.data);
                exit(1);
            }
            int run_status = 0;
            waitpid(run_pid, &run_status, 0);
            unlink(target_exec);
            return WEXITSTATUS(run_status);
        }
    }

    return 0;
}
EOF
"}

