#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

char *prepare_stdin() {
    char path[128];
    snprintf(path, sizeof(path), "/tmp/tcc_stdin_%d.c", getpid());
    FILE *f = fopen(path, "w");
    if (!f) return strdup("-");
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), stdin)) > 0) {
        fwrite(buf, 1, n, f);
